{
  "spells": [
    {
      "id": "spell_summon_13",
      "theory": "元素护卫术以两枚树脂为媒介，在施术者指定的空地上勾画临时契约环。魔力沿环线渗入地面，与当地游离的元素残响结合，聚成受契约约束的中阶护卫。护卫的形态随环境元素偏向而变，或为石屑缠绕的粗壮人形，或为水汽凝成的朦胧躯壳。其强度受契约条款与施术者自身能力双重限制，无法超出施术者能稳定供给的魔力上限。护卫只执行召唤时谈定的一项守护指令，超出指令范围便不再响应，也不会自行理解复杂意图。",
      "casting": "双膝微屈，以树脂在身前地面画出闭合环，环内压入代表守护对象的简符。双手按住环缘缓缓注入魔力，同时低声念出守护指令与时限。",
      "failure": "环线若有缺口，元素残响会四散逃逸，只留下几缕无意义的烟尘，树脂白白损耗。若指令念得含糊，护卫可能聚成两三个矮小的残次体，各自朝不同方向呆立，既不能合力守护，也不听从任何后续纠正，直到持续时间耗尽自行崩解。",
      "counters": [
        "用大量清水冲散契约环的纹路，元素便失去依附的骨架。",
        "在环内撒入铁屑扰乱元素流向，护卫会聚不成完整形体。",
        "以更强的同系元素护盾隔断施术者与环的联系，契约无法续力。"
      ],
      "socialConsequences": "河谷乡约允许村民在自家院落或公共空地召来护卫看守粮仓与牲畜，但见证人须在场确认指令内容，以免护卫被用于驱赶或恐吓邻里。城市公会要求施术者登记契约条款，护卫若在街头误伤行人，责任归施术者而非护卫本身。港口则关注护卫是否被用来封锁航道或威胁装卸工，航务管事会查验召唤地点与持续时间，超出登记的守护范围便按违规处置。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时护卫形体松散，需持续注视才能维持稳定。",
        "熟练度提升后，护卫能更准确地站到指定位置。",
        "较高熟练度使契约环闭合成败更少受风力干扰。",
        "高熟练度可让护卫在时限内保持形态不崩散。"
      ]
    },
    {
      "id": "spell_summon_14",
      "theory": "界门邀约以两枚树脂为引，在平坦地面上刻出向外延展的放射纹，纹路末端各压一枚树脂。魔力沿放射纹向外推送，形成一道狭窄的跨界传讯缝隙，向另一侧的存在发出措辞明确的来访邀约。邀约只传递条件与时限，不强迫对方应答，对方可拒绝或提出反条件。谈妥的条款会暂时烙印在纹路上，作为后续约束。若条款未谈妥，缝隙不会扩大为通道，仅维持传讯状态直到魔力耗尽。",
      "casting": "以树脂压住放射纹末端，掌心覆于纹心，缓缓注入魔力。待纹路泛起微光后，清晰说出邀约条件与等待时限，然后退开半步静候回应。",
      "failure": "若放射纹末端树脂滚动移位，缝隙会偏向一侧，邀约传到无关的方向，可能招来意料之外的低阶游魂在纹外徘徊。条件说得太急或含混，对方可能只接收片段，返回的答复与施术者本意不符，双方在误解中消耗魔力，最终缝隙闭合，邀约作废，树脂也失去效力。",
      "counters": [
        "用湿泥糊住放射纹末端，缝隙便无法向外推送邀约。",
        "在纹心压上一块冷铁，跨界传讯会被截断成杂音。",
        "以相反的放射纹覆盖原纹，可使邀约退回发出方向。"
      ],
      "socialConsequences": "河谷乡约视界门邀约为民事商谈，须有见证人在场记录条款，防止一方事后否认谈定内容。中陆城市要求施术者向公会报备邀约对象与目的，若邀约被用于诱骗或胁迫，则按精神强迫重罪论处。琥珀海岸港务特别留意跨界访客是否携带货物或疫病，谈妥的航运条款须与港务登记一致，否则视为逃避货损追责，邀约本身不违法，但借此掩盖事故责任则另案追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时放射纹微光不稳，邀约措辞容易传错。",
        "熟练度提高后，条件能更完整地送达对方。",
        "较高熟练度使等待时限的把握更为准确。",
        "高熟练度可让谈妥的条款烙印维持更久不散。"
      ]
    }
  ]
}
